TP.register({id:"lp9-gtk",lp:9,grade:"TK",mode:"baseline",nextGrade:"Kindergarten",build(E){const F=E.F;const X={tent:"tent",canoe:"canoe",pine:"pine",fire:"fire",mountain:"mountain",fish:"fish",deer:"deer",bear:"bear",owl:"owl",squirrel:"squirrel",otter:"otter",frog:"frog",pan:"pan",pack:"pack",hat:"topHat",soup:"soup",torch:"torch",sun:"sun",acorn:"acorn",leaf:"leaf",boot:"boot",map:"map",bird:"bluebird",cabin:"cabin",bridge:"bridge",swim:"swim",run:"run",row:"row",q:"question"};const COL={red:"#D9423A",blue:"#2F7FD9",green:"#3FA34D",yellow:"#F2C01E",orange:"#E08A2E"};const INK="#6B4A3C";const SKY="#CDEAF4",HILL="#9CC4B2",HILL_D="#6E9C88",HILL2="#8CB8A6",HILL2_D="#5E8C78",GRASS="#BCDCA4",GRASS_LN="#93BC7C",LAKE="#6FB6C8",LAKE_LN="#4E94A6",FOAM="#DCF2F6",DOCK="#D9A066",DOCK_D="#C08A5E",LOGC="#C9875A",LOGEND="#E0B07A",LOGLN="#A8724E",TRUNK="#A8724E",PINE_A="#8CC79A",PINE_B="#6FB183";const LABEL="#3E2C22";const r1=v=>Math.round(v*10)/10;const svg=(w,h,body,alt,dw)=>`<svg viewBox="0 0 ${w} ${h}" width="${dw||w}" role="img" aria-label="${alt||"Picture"}">${body}</svg>`;const em=(x,y,e,s)=>F.picXY(x,y,e,s)||`<text x="${x}" y="${y}" font-size="${s}" text-anchor="middle" dominant-baseline="central">${e}</text>`;const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const at=(x,y,k,inner)=>`<g transform="translate(${r1(x)} ${r1(y)}) scale(${r1(k)})">${inner}</g>`;const frame=(w,h,fill)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${fill||"var(--surface)"}" stroke="var(--line)" stroke-width="4"/>`;const col=(...a)=>`<div class="figure" style="flex-direction:column;align-items:center;gap:14px">${a.join("")}</div>`;const tag=(x,y,t)=>`<circle cx="${x}" cy="${y}" r="20" fill="var(--sea-soft)" stroke="var(--line)" stroke-width="2"/><text x="${x}" y="${y+1}" font-size="22" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${t}</text>`;function packIdeas(){const it=k=>{const d=window.TP_CAMP[k],h=170,w=h*d[1]/d[2];return{d:d[0],w,h}};const t=it(0),p=it(4);let b="";b+=`<image href="data:image/webp;base64,${t.d}" x="${r1(165-t.w/2)}" y="${r1(215-t.h)}" width="${r1(t.w)}" height="${r1(t.h)}"/>`;b+=`<image href="data:image/webp;base64,${p.d}" x="${r1(410-p.w/2)}" y="${r1(215-p.h)}" width="${r1(p.w)}" height="${r1(p.h)}"/>`;b+=em(640,125,X.boot,190);return svg(760,240,b,"A tent, a backpack, and a pair of boots",520)}function logPic(x,y,w,rot){const lw=w*.95,lh=lw*189/260;return`<image href="data:image/webp;base64,${window.TP_LOG}" x="${r1(x-lw/2)}" y="${r1(y-lh/2)}" width="${r1(lw)}" height="${r1(lh)}"${rot?` transform="rotate(${rot} ${r1(x)} ${r1(y)})"`:""}/>`}const put=(x,y,e,s)=>e==="LOG"?logPic(x,y,s):e==="PACK"?packPic(x,y,s):e==="TORCH"?torchPic(x,y,s):em(x,y,e,s);function torchPic(x,y,s){const w=s*1.3,h=w*149/252;return`<image href="data:image/webp;base64," x="${r1(x-w/2)}" y="${r1(y-h/2)}" width="${r1(w)}" height="${r1(h)}"/>`}function packPic(x,y,s){const d=window.TP_CAMP[4],h=s*1.15,w=h*d[1]/d[2];return`<image href="data:image/webp;base64,${d[0]}" x="${r1(x-w/2)}" y="${r1(y-h/2)}" width="${r1(w)}" height="${r1(h)}"/>`}function pineTree(x,base,h){const tw=Math.max(7,h*.12),th=h*.24;const lowW=h*.33,upW=h*.23;let b=`<rect x="${r1(x-tw/2)}" y="${r1(base-th)}" width="${r1(tw)}" height="${r1(th)}" rx="${r1(tw/2)}" fill="${TRUNK}" stroke="${INK}" stroke-width="2.6"/>`;b+=`<path d="M${r1(x-lowW)} ${r1(base-th+6)} L${r1(x)} ${r1(base-h*.62)} L${r1(x+lowW)} ${r1(base-th+6)} Z" fill="${PINE_B}" stroke="${INK}" stroke-width="2.8" stroke-linejoin="round"/>`;b+=`<path d="M${r1(x-upW)} ${r1(base-h*.54)} L${r1(x)} ${r1(base-h)} L${r1(x+upW)} ${r1(base-h*.54)} Z" fill="${PINE_A}" stroke="${INK}" stroke-width="2.8" stroke-linejoin="round"/>`;b+=at(x,base-h*.4,h/230,K_FACE(0,0,13,4.6));return b}function pineCone(x,y,s){const k=s/40;let b=`<g transform="translate(${r1(x)} ${r1(y)}) scale(${r1(k)})">`;b+=`<path d="M0 -24 C13 -14 15 2 10 16 C7 23 -7 23 -10 16 C-15 2 -13 -14 0 -24 Z" fill="#B5783F" stroke="${INK}" stroke-width="3" stroke-linejoin="round"/>`;b+=`<path d="M-11 -6 q11 8 22 0 M-12 4 q12 8 24 0 M-9 -15 q9 7 18 0" fill="none" stroke="#8A5A2B" stroke-width="2.6" stroke-linecap="round"/>`;return b+`</g>`}function kid(x,y,r,fill){return`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${INK}" stroke-width="3"/>`+at(x,y,r/26,K_FACE(0,0,12,4.4))}function skyPanel(w,h){let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${SKY}" stroke="var(--line)" stroke-width="4"/>`;b+=`<g fill="#FBFEFF" opacity=".9"><ellipse cx="${w*.74}" cy="56" rx="54" ry="22"/><ellipse cx="${w*.79}" cy="44" rx="36" ry="18"/><ellipse cx="${w*.68}" cy="46" rx="28" ry="16"/></g>`;return b}const hillBand=(w,base)=>`<path d="M20 ${base} L${w*.14} ${base-70} L${w*.28} ${base} Z" fill="${HILL}" stroke="${HILL_D}" stroke-width="3" stroke-linejoin="round"/><path d="M${w*.2} ${base} L${w*.36} ${base-96} L${w*.52} ${base} Z" fill="${HILL2}" stroke="${HILL2_D}" stroke-width="3" stroke-linejoin="round"/>`;const grassBand=(w,top,bot)=>`<path d="M8 ${top} Q${w*.3} ${top-10} ${w*.6} ${top+4} T${w-8} ${top-2} V${bot} H8 Z" fill="${GRASS}"/><path d="M8 ${top} Q${w*.3} ${top-10} ${w*.6} ${top+4} T${w-8} ${top-2}" fill="none" stroke="${GRASS_LN}" stroke-width="3.4" stroke-linecap="round"/>`;const lakeBand=(w,top,bot)=>`<path d="M8 ${top} Q${w*.3} ${top-8} ${w*.62} ${top+5} T${w-8} ${top} V${bot} H8 Z" fill="${LAKE}"/><path d="M8 ${top} Q${w*.3} ${top-8} ${w*.62} ${top+5} T${w-8} ${top}" fill="none" stroke="${LAKE_LN}" stroke-width="3.2" stroke-linecap="round"/><path d="M24 ${top+34} q22 -8 44 0 t44 0 t44 0 t44 0 t44 0 t44 0 t44 0" fill="none" stroke="${FOAM}" stroke-width="3.2" stroke-linecap="round" opacity=".85"/>`;const dockRun=(x0,x1,y)=>`<rect x="${x0}" y="${y}" width="${x1-x0}" height="14" rx="7" fill="${DOCK}" stroke="${INK}" stroke-width="3"/><path d="M${x0+20} ${y+14} v24 M${(x0+x1)/2} ${y+14} v28 M${x1-20} ${y+14} v24" fill="none" stroke="${DOCK_D}" stroke-width="6" stroke-linecap="round"/>`;const sceneWord=(x,y,t)=>`<text x="${x}" y="${y}" font-size="26" font-weight="700" text-anchor="middle" fill="${LABEL}">${t}</text>`;function cards(list,o){o=o||{};const c=o.cell||190,s=o.size||110,gap=16,extra=o.num?42:0,w=list.length*(c+gap)-gap+6,h=c+extra+6;let b="";list.forEach((e,i)=>{const x=3+i*(c+gap);b+=`<rect x="${x}" y="3" width="${c}" height="${c}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`+put(x+c/2,3+c/2,e,s);if(o.num)b+=`<text x="${x+c/2}" y="${c+34}" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">${i+1}</text>`});return svg(w,h,b,o.alt||"Picture cards")}function countPanel(groups,alt){const w=940,lh=88;let y=12,b="";groups.forEach((g,gi)=>{const e=g[0],n=g[1],per=g[2],cell=g[3],size=g[4],h=Math.ceil(n/per)*lh;if(gi)b+=`<path d="M22 ${y} H${w-22}" stroke="var(--line)" stroke-width="3"/>`;b+=tag(48,y+8+h/2,gi+1);for(let i=0;i<n;i++)b+=put(96+i%per*cell+cell/2,y+8+Math.floor(i/per)*lh+lh/2,e,size);y+=h+16});return svg(w,y+4,frame(w,y+4)+b,alt)}function cmpPanel(t,eA,nA,cellA,eB,nB,cellB,alt){const w=880,h=182;let b=frame(w,h)+tag(42,42,t);for(let i=0;i<nA;i++)b+=put(90+i*cellA+cellA/2,52,eA,56);for(let i=0;i<nB;i++)b+=put(90+i*cellB+cellB/2,132,eB,56);return svg(w,h,b,alt,800)}function scatterBox(e,n,seed,alt){const W=400,H=280;let x=seed,tries=0,gap=78;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};const pts=[];while(pts.length<n){const p=[56+rnd()*(W-112),54+rnd()*(H-108)];if(pts.every(q=>Math.hypot(q[0]-p[0],q[1]-p[1])>gap))pts.push(p);if(++tries>5e3){tries=0;gap-=4}}let b=frame(W,H);pts.forEach(p=>{b+=put(Math.round(p[0]),Math.round(p[1]),e,52)});return svg(W,H,b,alt,380)}const TRAY=[["g","b"],["t","s"],["t","b"],["g","s"],["t","s"],["g","b"],["g","s"],["t","b"]];function stone(x,y,r,grey){return`<ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r*.78}" fill="${grey?"#B9C2C8":"#D8B98E"}" stroke="${INK}" stroke-width="3.2"/><path d="M${x-r*.5} ${y-r*.3} q${r*.4} ${-r*.22} ${r*.8} 0" fill="none" stroke="${grey?"#95A0A8":"#BB9668"}" stroke-width="2.6" stroke-linecap="round"/>`}function trayFig(){return svg(520,520,`<image href="data:image/webp;base64," x="0" y="0" width="520" height="520"/>`,"A round tree stump with eight lake stones sitting on top of it. Four stones are grey and four are tan. Four are big and four are small.",400)}function pileFig(){return svg(640,419,`<image href="data:image/webp;base64," x="0" y="0" width="640" height="419"/>`,"A pile of eight autumn things by a stream: three acorns, three leaves and two fish.",520)}const TREES=[["A",100],["B",200],["C",150],["D",125],["E",175]];function treeRowFig(){return svg(1000,337,`<image href="data:image/webp;base64," x="0" y="0" width="1000" height="337"/>`,"Five cartoon pine trees in a row on the same ground, labeled A, B, C, D and E. B is the tallest and A is the shortest. From shortest to tallest they go A, C, E, D, B.",820)}function shapeFig(){return svg(900,600,`<image href="data:image/webp;base64," x="0" y="0" width="900" height="600"/>`,"A cartoon camp. A green triangle tent, a log cabin with a blue square window, a wooden dock with a long orange rectangle board on the front, and a round yellow sun",640)}function trailScene(){return svg(1000,649,`<image href="data:image/webp;base64," x="0" y="0" width="1000" height="649"/>`,"A camp beside a lake in the morning. A girl in a straw hat walks along a dirt trail carrying a gray bucket. Behind her is a green tent. Next is a tall pine tree with a squirrel sitting on a branch. At the right is a wooden dock that runs out over the lake. The sun is up in the sky.",660)}function coneScene(){return svg(900,591,`<image href="data:image/webp;base64," x="0" y="0" width="900" height="591"/>`,"Four pictures in two rows. Top left: a pine cone hanging on a branch in the snow, shut tight. An arrow points to the top right: the sun is out, the cone is open, and little seeds spin down. Bottom left: a squirrel sits with a pile of pine seeds. An arrow points to the bottom right: the squirrel is burying a seed in a hole, with small mounds of dirt nearby.",640)}function campScene(){return svg(900,600,`<image href="data:image/webp;base64," x="0" y="0" width="900" height="600"/>`,"A cartoon camp. A blue bird flies in the sky above a green tent. A blue backpack sits next to the tent. A pine tree stands between the tent and the wooden dock. A red canoe sits on the dock. Two fish swim in the lake. A mountain is far away behind the hills",640)}function packFig(){const w=460,h=300;let b=frame(w,h);{const d=window.TP_CAMP[4],h=170,w=h*d[1]/d[2];b+=`<image href="data:image/webp;base64,${d[0]}" x="${r1(230-w/2)}" y="${r1(285-h)}" width="${r1(w)}" height="${r1(h)}"/>`}b+=em(230,58,X.q,56)+em(88,96,X.q,38)+em(372,96,X.q,38);return svg(w,h,b,"A backpack with the flap buckled shut, with question marks above it.")}function ratherFig(){const a=svg(560,385,`<image href="data:image/webp;base64," x="0" y="0" width="560" height="385"/>`,"A red canoe floating on a blue lake with a paddle, mountains and pine trees behind it",330);const bb=svg(520,417,`<image href="data:image/webp;base64," x="0" y="0" width="520" height="417"/>`,"A dirt trail winding up through tall pine trees, with a wooden hiking sign",300);return`<div class="figure" style="align-items:center">${a}<span class="big">or</span>${bb}</div>`}function chartFig(){const w=820,h=240,r=30;let b=frame(w,h);b+=em(80,70,X.canoe,84);b+=em(80,172,X.swim,84);b+=`<path d="M150 20 V220" stroke="var(--line)" stroke-width="3"/>`;for(let i=0;i<6;i++)b+=TP_KIDPIC(196+i*96,70,72,30+i);for(let i=0;i<4;i++)b+=TP_KIDPIC(196+i*96,172,72,36+i);return svg(w,h,b,"A picture chart with two rows. The top row has a canoe and six faces. The bottom row has a swimmer and four faces.",780)}function patRow(num,list,size){const cell=96,w=list.length*cell+104,h=132;let b=frame(w,h);b+=tag(50,66,num);list.forEach((e,i)=>{b+=put(104+i*cell+cell/2,66,e,size||62)});b+=`<text x="${104+list.length*cell+28}" y="68" font-size="40" font-weight="800" text-anchor="middle" dominant-baseline="central" fill="var(--muted)">?</text>`;return svg(w+60,h,b,"A row of pictures that repeats, with a question mark at the end",Math.min(w+60,900))}function solidCards(){const st=`stroke="${INK}" stroke-width="4" stroke-linejoin="round"`;const card=(i,inner,lab)=>{const x=12+i*216,cx=x+98;return`<rect x="${x}" y="12" width="196" height="196" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/><g transform="translate(${x} 12)">${inner}</g><text x="${cx}" y="238" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">${lab}</text>`};let b="";b+=card(0,em(98,98,X.acorn,124),"1");b+=card(1,`<polygon points="98,42 162,152 34,152" fill="${COL.green}" ${st}/>`,"2");b+=card(2,`<polygon points="40,74 98,44 156,74 156,140 98,170 40,140" fill="${COL.orange}" ${st}/><path d="M40 74 L98 104 L156 74 M98 104 V170" fill="none" ${st}/>`,"3");b+=card(3,`<circle cx="98" cy="98" r="58" fill="${COL.blue}" ${st}/>`,"4");return svg(876,250,b,"Four cards: an acorn you could hold, a triangle drawn flat on the card, a box drawn so you can see three of its sides, and a circle drawn flat on the card",840)}function pairTreeFig(){const w=700,h=280,base=222;let b=frame(w,h);b+=`<path d="M40 ${base} H${w-40}" stroke="var(--line)" stroke-width="5" stroke-linecap="round"/>`;b+=pineTree(220,base,190);b+=pineTree(470,base,110);b+=`<text x="220" y="${base+40}" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">Tree 1</text>`;b+=`<text x="470" y="${base+40}" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">Tree 2</text>`;return svg(w,h,b,"Two pine trees standing on the same ground line. Tree 1 is tall and Tree 2 is short.",660)}const MIRA="Mira woke up first at camp. The lake was flat and shiny, and the whole hill smelled like pine. Mira wanted one more log for the campfire, so she took her bucket and walked down the trail. First she passed the green tent. Next she passed the tall pine tree, where a squirrel sat with its tail curled up. Then she came to the wooden dock. <strong>(Stop here. Ask what Mira will do next.)</strong> Mira walked out to the end of the dock and sat down. A little fish came up and looked at her toes. Mira laughed. Then she picked up the log lying beside the dock and carried it all the way back to camp.";const CONES="A pine tree grows its seeds inside a cone. The cone is hard and brown, and all winter long it stays shut tight. When summer comes and the air turns warm and dry, the cone opens up. Little seeds slip out from under the scales and spin down to the ground. Squirrels love pine seeds. A squirrel gathers up a pile of them and buries them in small holes all over the forest floor.";const LETTERS=["V","J","Q","Z","Y","K","T","R","B","S","v","j","q","z","y","k"];const NUMS=["6","2","9","4","1","8","3","10","5","7"];const FIND12=["D","a","G","e","N","o","P","h","M","u","F","w"];function findLetterFig(){const cell=152,per=6,w=per*cell+40,h=348;let b=frame(w,h);FIND12.forEach((L,i)=>{const cx=20+i%per*cell+cell/2,cy=26+Math.floor(i/per)*168;b+=`<rect x="${cx-56}" y="${cy}" width="112" height="128" rx="20" fill="#FBF1E4" stroke="${INK}" stroke-width="4"/>`;b+=window.TP_LETTER_CARD(L,cx,cy)});return svg(w,h,b,"Twelve cards laid out in two rows of six. Each card has one printed letter on it.")}const BENCH_SAMPLE="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. A child sitting right at that goal gets about 6 of these 10, which the suggested rating reads as approaching. Count the uppercase and the lowercase separately, hold each against the number above, and set the rating yourself.";const BENCH_DECK="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of any deck. A child sitting exactly at that goal still lands near 60 percent of whatever sample you show, and the suggested rating reads that as approaching. Set the rating yourself against those two counts.";const BENCH_FULL="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. The two inventories are scored under one code, so a child right at goal lands near 33 of 52 and the suggested rating reads that as approaching. Hold the uppercase count and the lowercase count against the two numbers above and set the rating yourself.";const ALPHA_FULL=E.alphabet({std:["TK.ELA.FLS.2.4"],sounds:false}).map(p=>Object.assign({},p,{key:p.key.concat([BENCH_FULL])}));const STOPS=[{id:1,title:"Trail Marker Letters",short:"Letters",parts:[{title:"Find the Letter",std:["TK.ELA.FLS.2.4"],n:10,dur:90,dir:"Listen to your teacher. Point to the letter on your screen.",desc:"matching a spoken letter name to its printed form (12 cards, 6 uppercase and 6 lowercase)",fig:()=>F.row(findLetterFig()),key:["Say: Here are twelve letter cards from the camp box. I will say a letter name. Point to the card with that letter.","Say: Point to the letter e. (top row, fourth card)","Say: Point to the letter N. (top row, fifth card)","Say: Point to the letter a. (top row, second card)","Say: Point to the letter w. (bottom row, sixth card)","Say: Point to the letter P. (bottom row, first card)","Say: Point to the letter u. (bottom row, fourth card)","Say: Point to the letter D. (top row, first card)","Say: Point to the letter h. (bottom row, second card)","Say: Point to the letter F. (bottom row, fifth card)","Say: Point to the letter G. (top row, third card)","The top row reads D, a, G, e, N, o and the bottom row reads P, h, M, u, F, w. Six cards are uppercase and six are lowercase, and two of the twelve are never asked for.","This is the direction the standard asks for: the child hears a name and finds the printed letter. Keep the uppercase and the lowercase results apart in your notes.","a, e and o are all small and round, and M and N look alike. If the child points to the wrong one of a pair, write down which one.","End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. A child sitting right at that goal gets about 6 of these 10, which the suggested rating reads as approaching. Count the uppercase and the lowercase separately, hold each against the number above, and set the rating yourself."]},{title:"Name the Letter",std:["TK.ELA.FLS.2.4"],kind:"words",full:ALPHA_FULL,words:LETTERS,unit:"Letter",n:16,dur:75,dir:"Say the name of each letter.",desc:"naming uppercase and lowercase letters (10 uppercase, 6 lowercase)",key:["Say: Every marker on the camp trail has a letter on it. Tell me the name of each letter. Click Next after each one.","Correct means the child says the letter name. If the child gives the sound instead, ask once: What is the name of this letter?","The first 10 are uppercase (V J Q Z Y K T R B S). The last 6 are lowercase (v j q z y k).","Each of the last 6 is the small version of one of the first 6, so you hear the same name twice and can tell which shape the child knows. Write down the ones missed.","End of TK goal: about 15 to 20 uppercase and 12 to 16 lowercase letter names. This deck is a sample of 16, so write the uppercase and lowercase results separately in your notes.","These letters are not the ones used in the earlier games. If you have those record sheets, compare them.","If the child misses 4 in a row, stop and write down how many were tried.","Find the Letter at the top of this stop is the part this standard is written for. The standard asks the child to match a spoken name to its printed form, and naming a letter on sight is harder than that, so rate this standard on the Find the Letter count and keep this deck as the extra note.",BENCH_DECK]}]},{id:2,title:"Count the Camp",short:"Count",parts:[{std:["TK.MATH.1.2"],n:6,dur:120,dir:"First count some small things from near you. Then count the pictures on the screen.",desc:"counting 10 or more real objects one by one where the teacher can see, then counting groups of 11, 13, 15, and 12 objects one by one on the screen",fig:()=>F.row(countPanel([["LOG",11,11,72,54],[X.acorn,13,7,110,58],[X.fish,15,8,100,56],[X.frog,12,6,110,58]],"Four groups to count: logs, acorns, fish, and frogs")),key:["Start with real things, before the screen. Say: Go and get ten small things you can hold, like spoons, blocks, socks or crayons, and set them on the table where I can see them. Then say: Move each one over to the side as you count it out loud. (One number word for each thing moved, no skips and no double counts. Moving each object is what makes the matching visible to you, so watch the hands as well as the numbers.)","Say: Push them back into a pile, add a few more, and count the whole lot again the same way. (Any number past ten. The goal is 10 or more with one number word for each object. If the count breaks down partway, write down the number it broke at.)","Those first two counts are the evidence for this standard, because they are the ones you can see for yourself. The screen rows below are still worth doing and they show whether a count holds together over bigger groups, but the child is pointing at a monitor you cannot see, so do not rate this standard on them alone and do not rate it on what an adult in the room reports.","Row 1. Say: Here is the wood pile for the campfire. Point to each log on your screen and count out loud. (11 logs in one line) Look for one number word for each log, with no skips and no double counts.","Row 2. Say: Now count the acorns. There are two lines of them. (13 acorns, in lines of 7 and 6)","Row 3. Say: Now count the fish. (15 fish, in lines of 8 and 7)","Row 4. Say: Now count the frogs. (12 frogs, in lines of 6 and 6)","Count an item correct only when the last number said matches the number of objects. On the screen rows, have the child say the numbers slowly enough that you can hear one number word for each picture, and watch the child's eyes move along the row. Where you cannot tell, leave the row out of the count rather than taking an adult's word for it.","Note where the count broke down: skipped a number, counted one twice, or lost track after 10."]}]},{id:3,title:"Sounds by the Water",short:"Sounds",parts:[{title:"First Sound Check",std:["TK.ELA.FLS.2.1"],n:4,dur:45,dir:"Listen to your teacher. Say the first sound.",desc:"saying the first sound of a pictured word",fig:()=>F.row(cards([X.deer,X.fish,X.soup,X.map],{cell:170,size:104,alt:"Deer, fish, soup, map"})),key:["Model first: Lake. The first sound in lake is /l/. Now you try.","Point to the deer. Say: Deer. What is the first sound in deer? (/d/)","Point to the fish. Say: Fish. What is the first sound in fish? (/f/)","Point to the soup. Say: Soup. What is the first sound in soup? (/s/) The card is a bowl of soup, so name it the soup, not the bowl.","Point to the map. Say: Map. What is the first sound in map? (/m/)","The answer is the sound, not the letter name. If the child says a letter name, ask: What sound do you hear first?"]},{title:"Rhyme Time",std:["TK.ELA.FLS.2.3"],n:3,dur:45,dir:"Listen to your teacher. Say a word that rhymes.",desc:"making a rhyme for a given word",fig:()=>F.row(cards([X.tent,X.bear,X.boot],{cell:180,size:110,alt:"Tent, bear, boot"})),key:["Model first: Camp, lamp, stamp. They rhyme. They sound the same at the end.","Point to the tent. Say: Tell me a word that rhymes with tent. (bent, went, sent, dent, zent)","Point to the bear. Say: Tell me a word that rhymes with bear. (chair, hair, pear, care, stair, zair)","Point to the boot. Say: Tell me a word that rhymes with boot. (root, hoot, scoot, fruit, zoot)","Real words and silly words both count. A rhyme that is close but not perfect counts too."]},{title:"Put It Together",std:["TK.ELA.FLS.2.2"],n:4,dur:45,dir:"Listen to the slow, sleepy voice. Say the whole word.",desc:"blending syllables and sounds into a word with picture support",fig:()=>F.row(cards([X.canoe,X.otter,X.pine,X.hat],{cell:170,size:104,alt:"A canoe, an otter, a pine tree, a hat"})),key:["Say: I am going to talk very slowly out here on the water. Put the parts together and tell me the word. The pictures can help you, but they are mixed up.","Say with a pause between the parts: ca ... noe. (canoe, the little boat in the first picture)","Say: ot ... ter. (otter, the swimming animal in the second picture)","Say the three sounds: /p/ ... /ie/ ... /n/. (pine)","Say the three sounds: /h/ ... /a/ ... /t/. (hat)","The first two are syllables. The last two are single sounds. Note which kind the child can blend."]}]},{id:4,title:"Numbers at Camp",short:"Numbers",parts:[{title:"Number Cards",std:["TK.MATH.1.5"],kind:"words",words:NUMS,unit:"Number",n:10,dur:45,dir:"Say the name of each number.",desc:"naming the numerals 1 to 10",key:["Say: The camp counts everything. What number is this? Click Next after each one.","Correct means the child says the number name. Write down the ones missed. Watch for 6 and 9 mixed up.","If the child counts up on fingers to find the name, note it. The goal is to know each numeral on sight."]},{title:"More or Fewer",std:["TK.MATH.1.6"],n:3,dur:50,dir:"Look at the pictures. Answer out loud.",desc:"comparing two groups by counting (more, same, fewer)",fig:()=>col(cmpPanel(1,"LOG",7,86,X.fish,4,86,"A row of seven logs above a row of four fish"),cmpPanel(2,X.tent,5,90,X.canoe,5,90,"A row of five tents above a row of five canoes"),cmpPanel(3,X.deer,4,200,X.acorn,9,70,"A row of four deer spread far apart above a row of nine acorns packed close together")),key:["Box 1. Say: Are there more logs or more fish? How do you know? (More logs. 7 logs and 4 fish.)","Box 2. Say: Are there more tents, more canoes, or the same number of each? (The same. 5 tents and 5 canoes.)","Box 3. Say: Which group has fewer, the deer or the acorns? (Fewer deer. 4 deer and 9 acorns. The deer are spread far apart and the acorns are packed close together, so the deer row reaches further across the box even though there are fewer of them.)","Look for counting, not guessing from how far a row reaches. Listen for the words more, same, fewer, or less.","If the child guesses from the length of the row in box 3, say: Let's count them together, and note that the answer needed help."]}]},{id:5,title:"Mira Walks to the Dock",short:"Mira",parts:[{std:["TK.ELA.R.3.2"],n:4,dur:90,read:MIRA,dir:"Listen to the story. Then answer out loud.",desc:"questions about the character, the order of three events, and what happens next in a story read aloud",html:()=>`<p class="big" style="text-align:center;margin:0 0 6px">Mira Walks to the Dock</p>`,fig:()=>F.row(trailScene()),key:["If picture supports are on, point to the picture before you read. Say: This is a camp beside a lake. A dock is a wooden walkway that goes out over the water. The girl in the picture is Mira, and she is carrying her bucket. The picture also shows the green tent, the tall pine tree with the squirrel, and the dock, the same things she walks past in the story.","Read the story out loud. Stop at the bold note, right after Mira comes to the dock.","Ask at the stopping place: What do you think Mira will do next? (Any guess that fits the story, like walk out on the dock, sit down, or look at the water.) Then read the rest.","Ask: Who is this story about? What did she want to find? (Mira. One more log for the campfire.)","Ask: Mira passed three things. What did she pass first? Next? Last? (First the green tent, next the tall pine tree, last the dock.) Count it correct when all three are in the right order.","Ask: What came up and looked at her toes? What did she carry back to camp? (A little fish. The log that was lying beside the dock.)","If picture supports are on, the picture on the screen can help the child remember. The picture shows Mira with her bucket, the green tent, the tall pine tree with the squirrel, and the dock."]}]},{id:6,title:"Stones and a Camp Chart",short:"Sort",parts:[{title:"Sort the Stones",std:["TK.MATH.2.5"],n:6,dur:60,dir:"Look at the tree stump and the pile. Answer out loud.",desc:"sorting and classifying objects by color, by size, by two attributes at once, and making a rule",fig:()=>col(trayFig(),pileFig()),key:["Point to the tree stump. Say: Here are the stones we picked up along the lake. How many stones are on the tree stump in all? (8)","Say: Sort them by color in your head. How many grey? How many tan? (4 grey and 4 tan)","Say: Now forget the color. Sort them by size. How many big? How many small? (4 big and 4 small)","Say: Now two things at once. Find the stones that are grey AND big. How many? (2)","Say: Find the stones that are tan AND small. How many? (2)","Point to the pile under the tree stump. Say: Put these into groups. How many groups did you make? Tell me your rule. (3 groups by what they are: 3 acorns, 3 leaves, 2 fish. Any rule the child can say and stick to counts, even one you did not expect.)","Sorting by two things at once is the hard part. If the child can sort by color and by size but not both at once, note that: one attribute is there and two is not yet."]},{title:"Camp Chart",std:["TK.MATH.3.4"],n:4,dur:60,dir:"Look at the chart. Answer out loud. Then make marks on your paper.",desc:"reading, copying, and adding to a picture chart with two groups",fig:()=>F.row(chartFig()),key:["Say: The children at camp picked what they like best, paddling the canoe or swimming at the dock. Each face is one child. How many children picked the canoe? (6)","Say: Did more children pick the canoe or swimming? (The canoe. 6 is more than 4.)","Say: On your paper, make one mark for each child who picked swimming. Hold it up. (4 marks, one for each face in the swimming row)","Say: One more child picks swimming. What should we add to the chart? (One more face in the swimming row, because each face is one child. That makes 5.)"]}]},{id:7,title:"How a Pine Tree Plants Itself",short:"Cones",parts:[{std:["TK.ELA.R.3.3"],n:3,dur:80,read:CONES,dir:"Listen to your teacher read about pine cones. Then answer out loud.",desc:"making an inference, making a connection, and asking a question about an informational text read aloud",fig:()=>F.row(coneScene()),key:["If picture supports are on, point to the picture first. Say: This shows what happens to a pine cone, in order. Top left: the cone is shut tight in the snow. Top right: the sun is out, the cone opens, and little seeds spin out. Bottom left: a squirrel gathers a pile of the seeds. Bottom right: the squirrel buries the seeds in small holes. Then read the facts out loud.","Ask: A squirrel buries more seeds than it can eat, and it does not dig up every hole again. What do you think happens to the seeds that stay in the ground? (They grow into new pine trees. The text does not say this part, so the child has to put two facts together.)","Ask: Have you ever watched an animal carry food away or hide it? Tell me about it. (Uses what the child already knows: a squirrel with a nut, a bird with a crumb, a dog with a bone, an ant with a crumb. Any real answer from the child's own life counts.)","Say: What do you want to know about pine trees? Ask me a question. You can start with What, Where, or Why. (Asks a real question about pine trees, cones, seeds, or the forest. Telling a fact instead of asking is not a question.)"]}]},{id:8,title:"Shapes Around Camp",short:"Shapes",parts:[{title:"Name the Shapes",std:["TK.MATH.4.1"],n:6,dur:65,dir:"Look at the shapes. Answer out loud. Then draw a shape on your paper.",desc:"naming, describing, and drawing circles, squares, rectangles, and triangles",fig:()=>F.row(shapeFig()),key:["Say: Here is the camp, drawn with shapes. What shape is the green tent? (triangle)","Say: What shape is the blue window on the cabin? (square)","Say: What shape is the long orange board on the front of the dock? (rectangle)","Say: What shape is the yellow sun? (circle)","Say: Tell me about the blue square. How many sides does it have? How many corners? (4 sides and 4 corners. Words like straight, flat, or even are a plus.)","Say: Draw a triangle on your paper. Hold it up. (A closed shape with 3 straight sides and 3 corners. It does not need to be neat or even.)"]},{title:"Where at Camp?",std:["TK.MATH.4.5"],n:6,dur:55,dir:"Look at the camp. Answer out loud.",desc:"position words (on, next to, in, above, between, near and far)",fig:()=>F.row(campScene()),key:["Say: Here is the whole camp. Look at the wooden dock. What is on the dock? (the canoe)","Say: What is next to the tent? (the backpack, or the pack)","Say: What is in the lake? (the fish)","Say: Look up in the sky right above the tent. What is up there? (the bird)","Say: What is between the tent and the dock? (the pine tree)","Say: Is the mountain near the camp or far from the camp? (far. The mountain is way off behind the hills.)","Look for a position word in the answer, not only a pointing finger. If the child only points, ask: Can you tell me with words?"]}]},{id:9,title:"Camp Notebook",short:"Write",parts:[{title:"Sound Letters",std:["TK.ELA.W.4.2"],n:4,dur:60,dir:"Listen for the sound. Write the letter on your paper and hold it up.",desc:"writing the letter for a beginning sound (l, t, p, b)",fig:()=>F.row(cards(["LOG",X.tent,X.pan,X.bird],{cell:180,size:110,alt:"A log, a tent, a pan, a bird"})),key:["Point to the first picture. Say: This is a log. Log starts with /l/. Write the letter that makes the /l/ sound. Hold it up. (l or L)","Point to the tent. Say: Tent starts with /t/. Write the letter for /t/. (t or T)","Point to the third picture. Say: This is a pan, the one we cook in. Pan starts with /p/. Write the letter for /p/. (p or P)","Point to the last picture. Say: This is a bird. Bird starts with /b/. Write the letter for /b/. (b or B)","A letter counts when you can tell what it is. Backward or wobbly letters still count. Uppercase or lowercase is fine.","You give the word and the sound. The child picks and writes the letter. If an adult names the letter for the child, do not count that one."]},{title:"Label Your Pack",std:["TK.ELA.W.4.4"],n:3,label:"checks met",dur:90,dir:"Draw one thing you would pack for camp. Write letters to tell what it is. Hold it up.",desc:"writing letters to label a drawing",sup:1,fig:()=>F.row(packIdeas()),key:["If picture supports are on, the tent, backpack, and boots are only ideas for what to bring. The child can draw anything.","Say: Draw one thing you would put in your pack for camp. Then write a word or some letters to tell what it is. Hold it up and tell me what you wrote.","Look for: writing that is separate from the drawing (letters or marks that look like letters, not only a picture).","Look for: 2 or more letters you can recognize. They do not need to spell the word.","Look for: the child tells you what the writing says, like It says hat. This shows the letters stand for a word or an idea.","If the child writes only a name, that is a fine start. Ask: What does it say? Then ask for some letters about the packed thing too."]}]},{id:10,title:"Tall Trees, Next in Line",short:"Line Up",parts:[{title:"Tallest Tree",std:["TK.MATH.3.2"],n:3,dur:45,dir:"Look at the trees. Answer out loud.",desc:"ordering five objects by height",fig:()=>F.row(treeRowFig()),key:["Point to the trees. Say: Five pine trees grow along the camp trail. Which tree is the tallest? (B)","Say: Which tree is the shortest? (A)","Say: Now put all five trees in order, from the shortest one to the tallest one. (A, C, E, D, B) Count it correct when all five are in the right order.","All five trees stand on the same line, so the child can compare the tops. Five in a row is harder than two. If the child can pick the tallest and the shortest but cannot order the middle three, write that down: the comparing is there and the ordering is not yet."]},{title:"What Comes Next?",std:["TK.MATH.2.6"],n:4,dur:60,dir:"Look at each row. Say what comes next.",desc:"extending repeating patterns and naming the part that repeats",fig:()=>col(patRow(1,[X.tent,X.pine,X.tent,X.pine,X.tent,X.pine,X.tent]),patRow(2,[X.fish,X.fish,X.frog,X.frog,X.fish,X.fish,X.frog,X.frog]),patRow(3,[X.acorn,X.leaf,"LOG",X.acorn,X.leaf,"LOG",X.acorn])),key:["Row 1. Say: Tent, pine, tent, pine, tent, pine, tent. What comes next? (a pine tree)","Row 2. Say: Look at this row. What comes next? (a fish. The pattern is fish, fish, frog, frog, and the row ends with the second frog.)","Row 3. Say: What comes next here? (a leaf. The pattern is acorn, leaf, log, and the row ends with an acorn.)","Go back to row 1. Say: What part keeps repeating over and over? (tent, pine)","Extra if there is time: clap and pat row 1 together (clap, pat, clap, pat). This shows the child can copy a pattern in a new way."]}]},{id:11,title:"Camp Chat",short:"Chat",parts:[{title:"Name It",std:["TK.ELA.L.1.1"],n:6,dur:55,dir:"Look at each picture. Answer out loud.",desc:"naming objects, actions, and describing words from pictures",fig:()=>F.row(cards([X.canoe,"PACK","TORCH",X.swim,X.run,X.owl],{cell:150,size:92,num:true,alt:"A canoe, a backpack, a flashlight, a person swimming, a person running, an owl"})),key:["Picture 1. Say: What is this? (a canoe or a boat. Both count.)","Picture 2. Say: What is this? (a backpack, a pack, or a bag.)","Picture 3. Say: You hold this in your hand and it makes a beam of light when it is dark. What is it called? (a flashlight. This is a harder word. A light or a lantern also counts.)","Picture 4. Say: What is this person doing? (swimming)","Picture 5. Say: What is this person doing? (running)","Picture 6. Say: This is an owl. Tell me two words about what an owl is like. (Describing words such as brown, soft, round, quiet, big eyed, little, awake at night.)","Pictures 1 to 3 are naming words, 4 and 5 are action words, and 6 is describing words. Note which kind was hard."]},{title:"Mystery Pack",std:["TK.ELA.LS.1.5"],n:3,label:"checks met",dur:55,dir:"Something is packed in the backpack. Ask your teacher questions to find out what it is.",desc:"asking questions and follow-up questions to find out information",fig:()=>F.row(packFig()),key:["Your secret: an apple is in the pack. Do not tell.","Say: One thing is packed in this backpack. Ask me questions to find out what it is. You can ask things like: Is it alive? What do you do with it?","Answer each question in a few words: It is not alive. It fits in your hand. It is red. It is round and smooth. You can eat it. It is a fruit. It goes crunch when you bite it.","Look for: asks a real question to get information (not only a guess, like A hat!).","Look for: asks a follow-up question that builds on your answer (after You can eat it, asks Is it sweet? or Is it a fruit?).","Look for: checks the idea with a question at the end (Is it an apple?). If the child is stuck after 4 or 5 questions, give one more clue."]},{title:"Lake or Trail",std:["TK.ELA.LS.1.7"],n:3,label:"checks met",dur:50,dir:"Pick one. Tell your teacher why.",desc:"sharing an opinion with a reason and details",fig:()=>ratherFig(),key:["Say: This afternoon you can paddle the canoe out on the lake, or you can hike up the trail through the pine trees. Which one would you pick? Tell me why.","Look for: tells an opinion (picks one).","Look for: gives a reason that explains the pick. If there is no reason, ask once: Why?","Say: Tell me more about your afternoon. What would you see out there? What would it feel like? Look for: 2 or more details in the description."]}]}];const LEVELUPS={1:{id:"L1",lv:true,title:"Level Up: Letter Names",std:["RF.K.1"],needs:["TK.ELA.FLS.2.4"],n:5,dir:"Say the name of each letter.",html:()=>F.cards(["W","G","U","r","g"],{size:"5rem",min:130}),key:["W (the name is double u)","G (the name is jee, and the sound is /g/)","U (the name is you)","r, the lowercase letter. Watch for r and n mixed up.","g, the lowercase letter. Watch for g mixed up with q or p.","TK asks for many letter names. Kindergarten asks for all 52 uppercase and lowercase letter names, so these are 5 that TK children miss most often. The name is the answer here, not the sound."]},2:{id:"L2",lv:true,title:"Level Up: How Many Altogether",std:["K.CC.B.4"],needs:["TK.MATH.1.2"],n:3,dir:"Count each group. Then tell your teacher how many there are.",html:()=>col(F.row(F.tenFrame(14)),F.row(scatterBox("LOG",9,27,"A mixed up group of logs"))),key:["Point to the ten frames at the top. Say: Count these dots and tell me how many there are in all. (14. Two full rows of five and then four more, with the second frame holding 4.)","Point to the mixed up logs underneath. Say: These are not lined up neatly. Count them and tell me how many. (9. Look for a plan, like touching each one on the screen so none is counted twice.)","Say: I will ask it a different way. How many logs were there altogether? (9, said straight back without recounting. Having to start the count over is worth a note.)","TK asks the child to count 10 or more objects one at a time, one number word per object. Kindergarten asks the child to answer the question how many, and to know that the last number said is the answer, for as many as 20 things in a line and as many as 10 scattered."]},4:{id:"L4",lv:true,title:"Level Up: Greater, Less, or Equal",std:["K.CC.C.6"],needs:["TK.MATH.1.6"],n:3,dir:"Look at the two boxes. Count, then answer out loud.",html:()=>col(F.row(scatterBox(X.acorn,9,11,"A group of acorns"),scatterBox(X.fish,7,23,"A group of fish")),F.row(scatterBox("LOG",8,5,"A group of logs"),scatterBox(X.frog,8,37,"A group of frogs"))),key:["Top pair. Ask: Which group is greater, the acorns or the fish? How do you know? (The acorns. 9 acorns and 7 fish. Look for counting, or for matching one fish to one acorn.)","Top pair again. Ask: So which group is less? (The fish. 7 is less than 9.)","Bottom pair. Ask: Are there more logs, more frogs, or are the two groups equal? (Equal. 8 logs and 8 frogs.)","TK asks for the words more, same, less or fewer. Kindergarten asks the child to say greater than, less than, or equal to, and to show it by counting or by matching the two groups one to one."]},8:{id:"L8",lv:true,title:"Level Up: Flat or Solid",std:["K.G.A.3"],needs:["TK.MATH.4.1"],n:4,dir:"Look at each picture. Say flat or solid.",html:()=>F.row(solidCards()),key:["Say first: A flat shape is like a drawing on paper. A solid shape is thick, and you could hold it in your hand. Then ask: Is number 1, the acorn, flat or solid? (solid)","Ask: Is number 2, the triangle drawn on the card, flat or solid? (flat)","Ask: Is number 3, the box, flat or solid? (solid)","Ask: Is number 4, the circle drawn on the card, flat or solid? (flat)","TK asks the child to name and describe shapes. Kindergarten asks the child to tell a flat shape from a solid one. Say the words flat and solid for the child first: the naming is the check, not the vocabulary."]},10:{id:"L10",lv:true,title:"Level Up: Which One, and How Much",std:["K.MD.A.2"],needs:["TK.MATH.3.2"],n:3,dir:"Look at the two trees. Answer out loud.",html:()=>F.row(pairTreeFig()),key:["Ask: Which tree is taller, Tree 1 or Tree 2? (Tree 1)","Ask: How do you know? (Both trees stand on the same ground line, so the one whose top is higher is taller. Look for the child lining up the bottoms, not just pointing.)","Ask: Now say it the other way. Tell me about Tree 2 in one sentence, using the word shorter. (Tree 2 is shorter than Tree 1. The sentence has to name both trees and use shorter or less tall.)","TK asks the child to put four or five objects in order by length or height. Kindergarten asks the child to compare two objects directly on one measurable attribute and to say which one has more of it, in words like taller than or shorter than."]}};let npOn={},tfOn={};function npHtml(){let h=`<div class="nl">`;for(let i=1;i<=15;i++)h+=`<button data-n="${i}" class="${npOn[i]?"on":""}" style="font-size:1.6rem">${i}</button>`;return h+`</div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){let c=`<div class="tf-wrap"><div class="tf">`;for(let k=0;k<10;k++)c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`;return c+`</div></div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear. The top row is a five frame.</p>`}function abcHtml(){return`<div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center">${"ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("").map(c=>`<span style="border:2px solid var(--line);border-radius:10px;padding:2px 10px;font-family:var(--font-display);font-weight:800;font-size:1.7rem">${c}${c.toLowerCase()}</span>`).join("")}</div>`}const TOOLS={np:{name:"Number path 1 to 15",std:["TK.MATH.1.2","TK.MATH.1.5","TK.MATH.1.6","K.CC.B.4","K.CC.C.6"],html:npHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{npOn[x.dataset.n]=!npOn[x.dataset.n];r()})},tf:{name:"Ten frame",std:["TK.MATH.1.2","TK.MATH.1.6","TK.MATH.2.5","TK.MATH.3.4","K.CC.B.4","K.CC.C.6"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},abc:{name:"Alphabet strip",std:["TK.ELA.W.4.2","TK.ELA.W.4.4","TK.ELA.FLS.2.4"],html:abcHtml},talk:{name:"Talking starters",std:["TK.ELA.LS.1.7"],html:()=>`<ul class="starters"><li>I would pick ____ because ____.</li><li>Out there I would see ____.</li><li>It would feel ____.</li></ul><p class="small">Say a starter out loud for the child to finish.</p>`}};const SUP_CAVEATS=[{t:"np",std:["TK.MATH.1.5"],msg:"The number path shows the numerals in order. If it was open during Number Cards, the child may have counted along the path to find a name. That is not the same as knowing the numeral on sight."},{t:"np",std:["TK.MATH.1.2","K.CC.B.4"],msg:"The number path helps the child keep the counting order. Note that the count was done with a visual."},{t:"np",std:["TK.MATH.1.6","K.CC.C.6"],msg:"The number path shows the numbers in order, so the child can see which one comes later. Note that the comparing was supported."},{t:"tf",std:["TK.MATH.1.6","K.CC.C.6"],msg:"If you matched the two groups on the ten frame, the child compared with a model you built. Note that the comparing was supported."},{t:"tf",std:["TK.MATH.2.5","TK.MATH.3.4"],msg:"If the ten frame was used to park each sorted group or each row of the chart, the child worked from a model you built. Note it."},{t:"abc",std:["TK.ELA.W.4.2","TK.ELA.W.4.4"],msg:"With the alphabet strip the child can find a letter and copy it. That still fits the standard, but note whether the child picked the right letter for the sound without help."},{t:"abc",std:["TK.ELA.FLS.2.4"],msg:"The alphabet strip shows every letter in order. If it was open during the letter tasks, the child may have sung the alphabet to find a name. That is not the same as knowing the letter on sight."},{t:"talk",std:["TK.ELA.LS.1.7"],msg:"The talking starter supplies the word because. Count the reason check as supported."},{t:"scribe",std:["TK.ELA.W.4.2","TK.ELA.W.4.4"],msg:"If an adult wrote the letters or guided the child's hand, those letters do not count as the child's writing."},{t:"adult",msg:"If the adult at home gave a hint or the answer, do not count that item as correct on the child's own."},{t:"objects",std:["TK.MATH.1.2","TK.MATH.1.6","TK.MATH.2.5","TK.MATH.3.2"],msg:"Counting, sorting or ordering real objects at home is a fine way to show this standard. Note what the child used and how many."},{t:"camp",msg:"A dock, a canoe, a pine cone and a pack are new to some children. If you had to explain a word like dock, canoe, cone, pack or trail, mark it here. Do not count an item wrong for not knowing a camp word."}];function stopLogs(st){const math=st.std.some(c=>/^TK\.MATH|^K\./.test(c)),write=st.std.some(c=>/\.W\.4\./.test(c)),out=["repeat","adult","camp"];if(math)out.push("objects");out.push("time");if(write)out.push("scribe");out.push("brk");return out}return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:[],stopLogs,logNames:{adult:"Adult at home helped",camp:"Explained a camp word"}}}});
